use super::*;

impl BugsEngine {
    /// ASSRT: `assert` whose first argument is not a logical condition.
    pub(crate) fn check_assert_condition(&self, node: Node, source: &str) -> Vec<Diagnostic> {
        if node.kind() != "function_call" {
            return Vec::new();
        }

        let func_name = match extract_call_name(node, source) {
            Some(n) => n,
            None => return Vec::new(),
        };

        if func_name != "assert" {
            return Vec::new();
        }

        let first_arg = match first_arg_node(node) {
            Some(n) => n,
            None => return Vec::new(),
        };

        // A condition must evaluate to a logical scalar. String and numeric
        // literals are not conditions.
        let is_non_condition = matches!(first_arg.kind(), "string" | "number");

        if is_non_condition {
            let pos = node.start_position();
            vec![Diagnostic {
                rule_id: "ASSRT",
                message: "The first input argument to 'assert' must be a condition. To always throw an error, use 'error(msg)' instead.".to_string(),
                severity: Severity::Error,
                byte_range: node.start_byte()..node.end_byte(),
                line: pos.row + 1,
                column: pos.column + 1,
                fix: None,
            }]
        } else {
            Vec::new()
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::test_util::has_id;

    // -- ASSRT ---------------------------------------------------------------

    #[test]
    fn assrt_fires_on_string_argument() {
        let src = "assert('some message');\n";
        let diags = node_diags(src);
        assert!(has_id(&diags, "ASSRT"), "got: {diags:?}");
    }

    #[test]
    fn assrt_fires_on_numeric_argument() {
        let src = "assert(5);\n";
        let diags = node_diags(src);
        assert!(has_id(&diags, "ASSRT"), "got: {diags:?}");
    }

    #[test]
    fn assrt_no_fire_on_logical_literal() {
        let src = "assert(true);\n";
        let diags = node_diags(src);
        assert!(!has_id(&diags, "ASSRT"), "got: {diags:?}");
    }

    #[test]
    fn assrt_no_fire_on_real_condition() {
        let src = "assert(x > 0);\n";
        let diags = node_diags(src);
        assert!(!has_id(&diags, "ASSRT"), "got: {diags:?}");
    }
}

use super::*;
use std::collections::HashSet;

impl BugsEngine {
    /// MOCUP: a variable is cleared (via `clear`/`clearvars`) but an `onCleanup`
    /// object whose cleanup function references that variable is still live, so
    /// the cleanup function will hit an undefined variable when it runs.
    pub(crate) fn check_mocup(&self, root: Node, source: &str) -> Vec<Diagnostic> {
        let mut cleared: Vec<(String, Node)> = Vec::new();
        let mut cleanup_refs: HashSet<String> = HashSet::new();
        Self::collect_mocup_info(root, source, &mut cleared, &mut cleanup_refs);

        let mut diagnostics = Vec::new();
        for (name, node) in cleared {
            if cleanup_refs.contains(&name) {
                let pos = node.start_position();
                diagnostics.push(Diagnostic {
                    rule_id: "MOCUP",
                    message: "Variable VAR_NAME may be cleared before the cleanup function that references VAR_NAME executes, resulting in an undefined variable error.".to_string(),
                    severity: Severity::Error,
                    byte_range: node.start_byte()..node.end_byte(),
                    line: pos.row + 1,
                    column: pos.column + 1,
                    fix: None,
                });
            }
        }
        diagnostics
    }

    fn collect_mocup_info(
        node: Node,
        source: &str,
        cleared: &mut Vec<(String, Node)>,
        cleanup_refs: &mut HashSet<String>,
    ) {
        if let Some(vars) = clear_command_vars(node, source) {
            for v in vars {
                cleared.push((v, node));
            }
        }

        if is_oncleanup_call(node, source) {
            let mut identifiers = HashSet::new();
            let mut call_names = HashSet::new();
            collect_identifiers(node, source, &mut identifiers);
            collect_function_call_names(node, source, &mut call_names);
            for id in identifiers.difference(&call_names) {
                cleanup_refs.insert(id.clone());
            }
        }

        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            Self::collect_mocup_info(child, source, cleared, cleanup_refs);
        }
    }
}

/// If `node` clears variables (via `clear`/`clearvars` in command or function
/// form), return the cleared variable names.
fn clear_command_vars(node: Node, source: &str) -> Option<Vec<String>> {
    match node.kind() {
        "command" => {
            let text = node_text(node, source).trim();
            let mut words = text.split_whitespace();
            if words.next() != Some("clear") {
                return None;
            }
            Some(
                words
                    .filter(|w| !w.starts_with('-'))
                    .map(|w| w.to_string())
                    .collect(),
            )
        }
        "function_call" => {
            let name = extract_call_name(node, source)?;
            if name != "clear" && name != "clearvars" {
                return None;
            }
            let vars = collect_call_args(node, source)
                .iter()
                .map(|a| a.trim().trim_matches(|c| c == '\'' || c == '"').to_string())
                .filter(|a| !a.is_empty() && !a.starts_with('-'))
                .collect();
            Some(vars)
        }
        _ => None,
    }
}

/// Whether `node` is an `onCleanup(...)` call.
fn is_oncleanup_call(node: Node, source: &str) -> bool {
    node.kind() == "function_call" && extract_call_name(node, source) == Some("onCleanup")
}

/// Collect all identifier names in the subtree.
fn collect_identifiers(node: Node, source: &str, out: &mut HashSet<String>) {
    if node.kind() == "identifier" {
        out.insert(node_text(node, source).trim().to_string());
    }
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        collect_identifiers(child, source, out);
    }
}

/// Collect all function-call name identifiers in the subtree.
fn collect_function_call_names(node: Node, source: &str, out: &mut HashSet<String>) {
    if node.kind() == "function_call" {
        if let Some(name) = node.child_by_field_name("name") {
            out.insert(node_text(name, source).trim().to_string());
        }
    }
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        collect_function_call_names(child, source, out);
    }
}

